4. Create a providers.tf file for configuring the Terraform providers. Here, we are initializing
K8s and Helm providers with the EKS cluster credentials provided to interact with the cluster. You
can download the providers.tf file from our GitHub repository at https://github.
com/PacktPublishing/Kubernetes-for-Generative-AI-Solutions/blob/
main/ch3/providers.tf:
provider " aws " {
region = local.region
}
provider " kubernetes " {
host = module.eks.cluster_endpoint
cluster_ca_certificate = base64decode(module.eks.cluster_
certificate_authority_data)
exec {
api_version = "client.authentication.k8s.io/v1beta1"
command = "aws"
args = ["eks", "get-token", "--cluster-name", module.eks.
cluster_name]
}
}
provider " helm " {
kubernetes {
host = module.eks.cluster_endpoint
cluster_ca_certificate = base64decode(module.eks.cluster_
certificate_authority_data)
exec {
api_version = "client.authentication.k8s.io/v1beta1"
command = "aws"
args = ["eks", "get-token", "--cluster-name", module.eks.
cluster_name]
}
}
}
