5. Create a vpc.tf file that will define the Amazon VPC, public and private subnets, internet
gateway, NAT gateway, and other networking resources required for the EKS cluster. Refer to the
AWS documentation at https://docs.aws.amazon.com/vpc/latest/userguide/
how-it-works.html to learn more about these concepts. You can download the vpc.
tf file from our GitHub repository at https://github.com/PacktPublishing/
Kubernetes-for-Generative-AI-Solutions/blob/main/ch3/vpc.tf:
module " vpc " {
source = "terraform-aws-modules/vpc/aws"
version = "~> 5.21"
name = local.name
cidr = local.vpc_cidr
azs = local.azs
private_subnets = [for k, v in local.azs: cidrsubnet(local.
vpc_cidr, 4, k)]
public_subnets = [for k, v in local.azs: cidrsubnet(local.
vpc_cidr, 8, k + 48)]
enable_nat_gateway = true
single_nat_gateway = true
public_subnet_tags = {
"kubernetes.io/role/elb" = 1
}
private_subnet_tags = {
"kubernetes.io/role/internal-elb" = 1
"karpenter.sh/discovery" = local.name
}
}
output vpc_id {
description = "VPC ID"
value = "${module.vpc.vpc_id}"
}
